// SPDX-License-Identifier: CC0-1.0
#ifndef DIJKSTRA_LIBRARY
#error Define DIJKSTRA_LIBRARY as a quoted absolute filename.
#endif
#include DIJKSTRA_LIBRARY
#include <chrono>
#include <cstdio>
#include <cstdlib>
#include <string>
#include <numeric>
#include <cinttypes>
#include <memory>
struct BenchCase { std::string name; int n; int parameter; };
static const std::vector<BenchCase> cases = {
 {"chain_small",32,0},{"chain_boundary",256,0},{"chain_above_boundary",257,0},{"chain_large",300000,0},
 {"star_small",64,0},{"star_boundary",256,0},{"star_above_boundary",257,0},{"star_large",300000,0},
 {"grid_small",64,8},{"grid_medium",4096,64},{"grid_large",199809,447},
 {"sparse_small",64,4},{"sparse_medium",4096,4},{"sparse_large",200000,4},
 {"dense_small",64,32},{"dense_medium",1024,256},{"dense_large",4096,128},
 {"zero_one_small",64,4},{"zero_one_large",200000,4},
 {"zero_small",64,4},{"zero_large",200000,4},
 {"large_weight_small",64,4},{"large_weight_large",200000,4},
 {"reach_small",64,16},{"reach_large",500000,32},
 {"improve_small",64,16},{"improve_medium",4096,16},{"improve_large",50000,8},
 {"hub_small",64,0},{"hub_large",300000,0},
 {"fork_chain_large",300000,0},{"chain_fork_large",300000,0},{"forced_cycle_large",300000,0}
};
static std::uint64_t rng_state;
static std::uint64_t random_value() {
 auto z=(rng_state+=0x9e3779b97f4a7c15ULL); z=(z^(z>>30))*0xbf58476d1ce4e5b9ULL;
 z=(z^(z>>27))*0x94d049bb133111ebULL; return z^(z>>31);
}
static WGraph make_graph(const BenchCase& c) {
 rng_state=0xa8500c11999ULL; WGraph g(c.n);
 const auto add=[&](int u,int v,std::int64_t w){g[u].emplace_back(v,w);};
 if(c.name=="fork_chain_large" || c.name=="chain_fork_large" || c.name=="forced_cycle_large") {
  const int dead=c.n-2;
  std::vector<int> order;
  for(int i=0;i<c.n-1;++i) if(i!=dead) order.push_back(i);
  for(std::size_t i=order.size();i>2;--i) std::swap(order[i-1],order[1+random_value()%(i-1)]);
  order.push_back(c.n-1);
  for(std::size_t i=1;i<order.size();++i)add(order[i-1],order[i],1);
  if(c.name=="fork_chain_large")add(0,dead,0);
  else if(c.name=="chain_fork_large")add(order[order.size()/2],dead,0);
  else add(order.back(),0,0);
 }
 else if(c.name.starts_with("chain")) for(int i=1;i<c.n;++i) add(i-1,i,1);
 else if(c.name.starts_with("star")) for(int i=1;i<c.n;++i) add(0,i,(std::int64_t{i}*998244353)%1000000001);
 else if(c.name.starts_with("grid")) {
  for(int i=0;i<c.n;++i) {if(i%c.parameter+1<c.parameter)add(i,i+1,random_value()%1000000001);
   if(i+c.parameter<c.n)add(i,i+c.parameter,random_value()%1000000001);}
 } else if(c.name.starts_with("reach")) for(int i=1;i<c.parameter;++i)add(i-1,i,1);
 else if(c.name.starts_with("improve")) {
  for(int v=1;v<c.n;++v)for(int d=c.parameter;d>=1;--d)add(0,v,std::int64_t{d}*1000000+v);
 } else if(c.name.starts_with("hub")) {
  for(int i=1;i<c.n;++i)add(0,i,1000000000-i);
  for(int i=1;i<c.n-1;++i)add(c.n-1,i,i);
 } else {
  const auto weight=[&]() -> std::int64_t {
   if(c.name.starts_with("zero_one")) return random_value()&1;
   if(c.name.starts_with("zero")) return 0;
   if(c.name.starts_with("large_weight"))return 1000000000-random_value()%32;
   return random_value()%1000000001;
  };
  for(int i=1;i<c.n;++i)add(i-1,i,weight());
  for(int u=0;u<c.n;++u)for(int j=0;j<c.parameter;++j)add(u,random_value()%c.n,weight());
 }
 return g;
}
static std::uint64_t checksum(const std::vector<std::int64_t>& d,const std::vector<int>& p) {
 std::uint64_t sum=0x5434543; for(auto x:d)sum=sum*1000003+static_cast<std::uint64_t>(x);
 for(auto x:p)sum=sum*1000033+x;
 return sum;
}

using RunFunction = void (*)(const WGraph&,std::vector<std::int64_t>&,int,int,std::vector<int>&);
[[gnu::noinline]] static void RunDistance(const WGraph& g,std::vector<std::int64_t>& d,int start,int,std::vector<int>&) { Dijkstra(g,d,start); }
[[gnu::noinline]] static void RunPath(const WGraph& g,std::vector<std::int64_t>& d,int start,int target,std::vector<int>& p) { Dijkstra(g,d,start,target,p); }
static volatile std::uint64_t cache_sink;
[[gnu::noinline]] static void condition_graph(const WGraph& g) {
 std::uint64_t sum=0;
 for(const auto& edges:g)for(const auto& e:edges)sum+=static_cast<std::uint64_t>(e.w)+e.to;
 cache_sink=sum;
}
int main(int argc,char** argv) {
 const std::string filter=argc>1?argv[1]:"improve_small";
 const std::string api=argc>2?argv[2]:"path";
 const std::string mode=argc>3?argv[3]:"fresh";
 const int rounds=argc>4?std::atoi(argv[4]):21;
 const int warmups=argc>5?std::atoi(argv[5]):3;
 const RunFunction function=api=="path"?RunPath:RunDistance;
 for(const auto& c:cases) {
  if(filter!="all" && filter!=c.name)continue;
  const WGraph g=make_graph(c);
  const int source=0,target=c.n-1;
  std::size_t edges=0;for(const auto& a:g)edges+=a.size();
  const int batch=argc>6?std::atoi(argv[6]):(c.n<=64?1000:c.n<=257?300:c.n<=4096?10:1);
  std::vector<std::int64_t> d;std::vector<int> p;
  RunDistance(g,d,source,target,p);const auto reference=d;
  const auto expected=checksum(reference,{});
  std::vector<double> samples;
  for(int round=-warmups;round<rounds;++round) {
   if(mode=="fresh") {std::vector<std::int64_t>().swap(d);std::vector<int>().swap(p);}
   else {d.assign(reference.begin(),reference.end());p.clear();}
   condition_graph(g);
   const auto begin=std::chrono::steady_clock::now();
   for(int b=0;b<batch;++b) {
    if(mode=="fresh" && b!=0) {std::vector<std::int64_t>().swap(d);std::vector<int>().swap(p);}
    function(g,d,source,target,p);
   }
   const auto end=std::chrono::steady_clock::now();
   const auto actual=checksum(d,{});
   if(actual!=expected || d!=reference) return 2;
   if(round>=0)samples.push_back(std::chrono::duration<double,std::nano>(end-begin).count()/batch);
  }
  auto sorted=samples;std::sort(sorted.begin(),sorted.end());
  std::printf("{\"case\":\"%s\",\"api\":\"%s\",\"mode\":\"%s\",\"variant\":\"single\",\"vertices\":%d,\"edges\":%zu,\"batch\":%d,\"rounds\":%d,\"warmups\":%d,\"median_ns\":%.4f,\"checksum\":%ju,\"samples_ns\":[",c.name.c_str(),api.c_str(),mode.c_str(),c.n,edges,batch,rounds,warmups,sorted[sorted.size()/2],static_cast<std::uintmax_t>(expected));
  for(std::size_t i=0;i<samples.size();++i)std::printf("%s%.4f",i?",":"",samples[i]);
  std::puts("]}");
 }
}

