// Independent label-correcting Bellman--Ford, no heap and no candidate helper.
static std::vector<std::int64_t> reference(const WGraph &g, int s) {
    std::vector<std::int64_t> d(g.size(), INF); d[s] = 0;
    for (std::size_t iteration = 1; iteration < g.size(); ++iteration) {
        bool changed = false;
        for (std::size_t u = 0; u < g.size(); ++u) if (d[u] != INF)
            for (const auto &e : g[u]) if (d[e.to] > d[u] + e.w) {
                d[e.to] = d[u] + e.w; changed = true;
            }
        if (!changed) break;
    }
    return d;
}
static void check_path(const WGraph &g, const std::vector<std::int64_t> &d,
                       const std::vector<int> &path, int s, int t) {
    if (d[t] == INF) { require(path.empty(), "unreachable path"); return; }
    require(!path.empty(), "empty reachable path");
    require(path.front() == s && path.back() == t, "path endpoints");
    require(path.size() <= g.size(), "path cycle");
    std::int64_t total = 0;
    for (std::size_t i = 1; i < path.size(); ++i) {
        require(path[i] >= 0 && static_cast<std::size_t>(path[i]) < g.size(), "path vertex range");
        std::int64_t weight = INF;
        for (const auto &e : g[path[i - 1]]) if (e.to == path[i]) weight = std::min(weight, e.w);
        require(weight != INF, "nonedge path");
        total += weight;
    }
    require(total == d[t], "path length");
