static WGraph bounded_frontier_graph(int n, int width, int prefix, bool spill) {
    WGraph g(n);
    for(int u=0;u<prefix;++u)g[u].emplace_back(u+1,1);
    const int first=prefix+1;
    for(int c=0;c<width;++c)g[prefix].emplace_back(first+c,1);
    for(int layer=0;layer<2;++layer)for(int c=0;c<width;++c) {
        const int u=first+layer*width+c;
        g[u].emplace_back(u+width,1);
        g[u].emplace_back(u,0); // A non-improving entry between successful updates.
        if(spill && layer==0 && c==0)for(int k=0;k<4;++k)
            g[u].emplace_back(first+3*width+k,1'000'000'000);
    }
