    check_policy<false,false,true>(g,seed,s,t);
    check_policy<true,true,false>(g,seed,s,t);
    check_policy<true,true,true>(g,seed,s,t);
    check_policy<true,false,false>(g,seed,s,t);
    check_policy<true,false,true>(g,seed,s,t);
